#!/usr/bin/env python3
"""Embed the Metal shader for one-time compilation on the device."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
source = (root / 'ios/Hangtime/NewPixie.metal').read_text()
assert '"""#' not in source
(root / 'ios/Hangtime/ShaderSource.swift').write_text(
    '// Generated by scripts/generate_shader_source.py from NewPixie.metal.\n'
    'enum NewPixieShader {\n    static let source = #"""\n' + source + '\n"""#\n}\n')
